<?php require_once __DIR__ . '/../includes/auth.php'; require_admin(); require_once __DIR__ . '/../config/database.php'; require_once __DIR__ . '/../includes/functions.php'; $id=(int)$_POST['id']; $name=trim($_POST['name']??''); $desc=trim($_POST['description']??''); if(!preg_match('/^[A-Za-zÇĞİÖŞÜçğıöşü0-9\s]{2,100}$/u',$name)){set_flash('danger','Invalid name format.'); redirect('edit.php?id='.$id);} $stmt=$conn->prepare('UPDATE roles SET name=?, description=? WHERE id=?'); $stmt->bind_param('ssi',$name,$desc,$id); $stmt->execute(); set_flash('success','Role updated.'); redirect('index.php'); ?>
